 async function asset360Tab(id,tab,button){
  document.querySelectorAll('[data-asset360-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===button)));const panel=q('#asset360-panel');panel.innerHTML='<div class="asset360-loading">Loading '+escape(title(tab))+'…</div>';
  if(tab==='overview'){const d=await api('/api/assets/'+id+'/360'),a=d.asset,ass=d.current_assignment;panel.innerHTML=`<div class="asset360-overview-grid"><article><h3>Identity</h3><dl><dt>Asset Tag</dt><dd>${escape(a.asset_tag||'—')}</dd><dt>Barcode</dt><dd>${escape(a.barcode||'—')}</dd><dt>Serial</dt><dd>${escape(a.serial_number||'—')}</dd></dl></article><article><h3>Classification</h3><dl><dt>Manufacturer</dt><dd>${escape(a.manufacturer_name||'—')}</dd><dt>Model</dt><dd>${escape(a.model_name||a.model_number||'—')}</dd><dt>Category</dt><dd>${escape(a.category_name||'—')}</dd><dt>Type</dt><dd>${escape(a.type_name||'—')}</dd><dt>Class</dt><dd>${escape(a.class_name||'—')}</dd></dl></article><article><h3>Custody</h3><dl><dt>Current Custodian</dt><dd>${ass?escape(ass.first_name+' '+ass.last_name):'Unassigned'}</dd><dt>Employee Number</dt><dd>${ass?escape(ass.employee_number):'—'}</dd><dt>Current Location</dt><dd>${escape(a.location_name||'—')}</dd></dl></article></div>`;return;}
  try{
   const d=await api('/api/assets/'+id+'/360/'+tab),list=d.rows||d.history||[];
   if(tab==='photos'){panel.innerHTML=list.length?`<div class="asset360-gallery">${list.map(x=>`<figure><a href="/api/files/${x.file_id}" target="_blank" rel="noopener"><div class="asset360-thumb">View</div></a><figcaption><strong>${escape(x.evidence_type||x.document_type)}</strong><span>${escape(x.caption||x.original_filename)}</span><small>${escape(x.captured_at||x.uploaded_at||'')}</small></figcaption></figure>`).join('')}</div>`:'<div class="empty">No reference photos yet.<br><button data-upload-asset="'+id+'">Add Photos</button></div>';return;
   }
   if(tab==='assignment'){const current=d.current;panel.innerHTML=`<article class="asset360-section"><h3>Current Custodian</h3>${current?`<p><strong>${escape(current.first_name+' '+current.last_name)}</strong><br>${escape(current.employee_number)} · ${escape(current.department_name||'')} · ${escape(current.location_name||'')}<br>Assigned: ${escape(current.assigned_date)}</p>${user.super||user.permissions.includes('organization.view')?`<img src="/api/employees/${current.employee_id}/photo" alt="Custodian profile photo" width="96" height="96" style="object-fit:cover;border-radius:12px" onerror="this.hidden=true">`:''}${user.super||user.permissions.includes('organization.manage')&&user.permissions.includes('files.manage')?`<button data-employee-photo="${current.employee_id}" data-asset-id="${id}">Update employee photo</button>`:''}`:'<div class="empty">No current assignment.</div>'}<h3>Assignment History</h3>${table360(d.history||[])}</article>`;return;}
   if(tab==='procurement'){const r=d.reconciliation||{};panel.innerHTML=`<div class="procurement-chain"><article><small>Purchase Order</small><strong>${escape(d.purchase_order?.po_number||'Not linked')}</strong></article><span>→</span><article><small>Delivery Receipt</small><strong>${escape(d.delivery_receipt?.dr_number||'Not linked')}</strong></article><span>→</span><article><small>Invoice</small><strong>${escape(d.invoice?.invoice_number||'Not linked')}</strong></article><span>→</span><article><small>Asset</small><strong>#${escape(id)}</strong></article></div><div class="reconciliation">${[['PO Found',r.po_found],['DR Found',r.dr_found],['Invoice Found',r.invoice_found],['Serial Recorded',r.serial_recorded]].map(([l,v])=>`<span class="${v?'ok':'missing'}">${v?'✓':'○'} ${l}</span>`).join('')}</div>`;return;}
   if(tab==='timeline'){panel.innerHTML=list.length?`<div class="asset360-timeline">${list.map(x=>`<article><time>${escape(x.date)}</time><div><strong>${escape(x.title)}</strong><p>${escape(x.detail||'')}</p></div></article>`).join('')}</div>`:'<div class="empty">No lifecycle evidence recorded yet.</div>';return;}
   if(tab==='documents'){panel.innerHTML=list.length?table360(list.map(x=>({Type:x.document_type,Reference:x.original_filename,Date:x.uploaded_at,Action:'Open file #'+x.file_id}))):'<div class="empty">No procurement or lifecycle documents linked.</div>';return;}
   if(tab==='financial'&&d.row){panel.innerHTML=table360([d.row])+(d.depreciation?.length?'<h3>Depreciation</h3>'+table360(d.depreciation):'');return;}
   if(tab==='technical'&&d.row){panel.innerHTML=table360([d.row]);return;}
   panel.innerHTML=list.length?table360(list):'<div class="empty">No '+escape(title(tab))+' records available.</div>';
  }catch(e){panel.innerHTML='<div class="empty">'+escape(e.message)+'</div>';}
 }
 function table360(rows){
  if(!rows?.length)return '<div class="empty">No records.</div>';const keys=Object.keys(rows[0]).filter(k=>!/_id$/.test(k)&&!['asset_id','file_id','old_values','new_values'].includes(k)).slice(0,8);
  return '<div class="table-scroll"><table class="records-data-table"><thead><tr>'+keys.map(k=>'<th>'+escape(fieldLabel(k))+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+keys.map(k=>'<td data-label="'+escape(fieldLabel(k))+'"><span>'+escape(r[k]??'—')+'</span></td>').join('')+'</tr>').join('')+'</tbody></table></div>';
 }
 window.mdmCloudScan=async barcode=>{try{const d=await api('/api/scan','POST',{barcode,inventory_session_id:q('#scan-session')?.value||null,location_id:q('#scan-location')?.value||null,device_type:matchMedia('(max-width: 700px)').matches?'PHONE':'DESKTOP'});const result=q('#cloud-scan-result');if(d.asset){result.innerHTML='<div class="cloud-scan-banner success"><div><span class="result-kicker">✓ Asset Found</span><strong>'+escape(d.asset.asset_tag||barcode)+'</strong><span>'+escape(d.asset.description||d.asset.model_name||'Registered asset')+'</span></div><button type="button" data-open-asset="'+escape(d.asset.asset_id)+'">Quick View</button></div>';}else{result.innerHTML='<div class="cloud-scan-banner warning"><div><span class="result-kicker">⚠ Asset Not Registered</span><strong>'+escape(barcode)+'</strong><span>No matching shared asset record was found.</span></div></div>';}return d;}catch(e){q('#cloud-scan-result').innerHTML='<div class="cloud-scan-banner danger"><div><span class="result-kicker">Connection Issue</span><span>'+escape(e.message)+'</span></div></div>';return {error:e.message};}};
 window.mdmAssetLookup=async term=>{const value=String(term||'').trim();if(!value)return null;const result=q('#cloud-scan-result');result.innerHTML='<div class="cloud-scan-banner neutral"><div><span class="result-kicker">Searching</span><span>Looking up '+escape(value)+'…</span></div></div>';try{const d=await api('/api/records/assets?q='+encodeURIComponent(value)+'&limit=20');const rows=d.rows||[];const normalized=value.toLowerCase();const asset=rows.find(a=>[a.asset_tag,a.barcode,a.serial_number,a.hostname,a.imei,a.mac_address].some(v=>String(v||'').toLowerCase()===normalized))||rows[0];if(asset){result.innerHTML='<div class="cloud-scan-banner success"><div><span class="result-kicker">✓ Asset Found</span><strong>'+escape(asset.asset_tag||asset.barcode||value)+'</strong><span>'+escape(asset.description||asset.model_name||asset.serial_number||'Registered asset')+'</span></div><button type="button" data-open-asset="'+escape(asset.asset_id)+'">Quick View</button></div>';return asset;}result.innerHTML='<div class="cloud-scan-banner warning"><div><span class="result-kicker">⚠ Asset Not Registered</span><strong>'+escape(value)+'</strong><span>No matching asset tag, barcode, or serial number was found.</span></div></div>';return null;}catch(e){result.innerHTML='<div class="cloud-scan-banner danger"><div><span class="result-kicker">Lookup Failed</span><span>'+escape(e.message)+'</span></div></div>';return null;}};
 q('#cloud-form').onsubmit=async e=>{e.preventDefault();const button=q('#cloud-save'),error=q('#cloud-error');error.hidden=true;if(!validateCloudForm())return;button.disabled=true;const original=button.textContent;button.textContent='Saving…';try{let d=Object.fromEntries(new FormData(e.target));for(const [k,v]of Object.entries(d)){if(v==='')delete d[k];else if(meta[currentTable]?.columns.find(c=>c.name===k)?.type==='DATETIME')d[k]=new Date(v).toISOString();}d=await resolveAssetModel(d);await submitHandler(d);q('#cloud-dialog').close();}catch(err){error.textContent=err.message||'The record could not be saved.';error.hidden=false;error.scrollIntoView({behavior:'smooth',block:'nearest'});}finally{button.disabled=false;button.textContent=original;}};
 q('#cloud-close').onclick=()=>q('#cloud-dialog').close();q('#asset-close').onclick=()=>q('#asset-dialog').close();q('#cloud-export').onclick=async()=>{try{const d=await api('/api/export/'+currentTable+'?q='+encodeURIComponent(q('#cloud-search').value)+'&limit=500');const url=URL.createObjectURL(new Blob([d.csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=currentTable+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(x){alert(x.message);}};q('#new-record').onclick=()=>recordForm();q('#refresh-records').onclick=()=>{invalidate(currentTable);loadRecords();};q('#module-select').onchange=()=>{currentTable=q('#module-select').value;q('#cloud-search').value='';loadRecords();};
