 (async()=>{try{const result=await api('/api/metadata');meta=result.tables;user=result.user;q('#account-role').textContent=user.roles.join(', ').replaceAll('_',' ');if(q('#account-name'))q('#account-name').textContent=user.name||user.display_name||user.username||q('#account-email')?.textContent?.split('@')[0]||'Account';q('#module-select').innerHTML=Object.entries(meta).sort(([a],[b])=>a==='assets'?-1:b==='assets'?1:a.localeCompare(b)).map(([t,m])=>`<option value="${t}">${title(m.module)} · ${title(t)}</option>`).join('');q('#module-select').value='assets';q('#cloud-export').hidden=!(user.super||user.permissions.includes('exports.view'));q('#import-local').hidden=!user.super;q('#users-nav').hidden=!user.super;document.querySelectorAll('[data-page="scanner"]').forEach(el=>el.hidden=!(user.super||user.permissions.includes('barcode.manage')));const startup=[];if(!q('#records').hidden)startup.push(loadRecords());if(meta.assets)startup.push(dashboard());const sessionsPromise=meta.inventory_sessions?data('inventory_sessions'):Promise.resolve([]),locationsPromise=meta.locations?data('locations'):Promise.resolve([]);const [,sessions,locations]=await Promise.all([Promise.all(startup),sessionsPromise,locationsPromise]);if(meta.inventory_sessions)q('#scan-session').innerHTML+=sessions.filter(s=>s.status==='ACTIVE').map(s=>{const expected=s.expected_count??s.expected_assets??s.total_expected??s.asset_count??'';return `<option value="${s.inventory_session_id}" data-expected="${escape(expected)}">${escape(s.session_name)}</option>`}).join('');if(meta.locations)q('#scan-location').innerHTML+=locations.map(l=>`<option value="${l.location_id}">${escape(l.location_name)}</option>`).join(''); }catch(e){q('#cloud-stats').textContent=e.message;}})();
